subprocess_js:
import js
from pyodide.ffi import to_js
result = {'ok': False}
try:
    cp = await js.eval("import('node:child_process')")
    result['ok'] = len(str(cp.execSync('echo hi', to_js({'encoding': 'utf8'}, dict_converter=js.Object.fromEntries)))) > 0
except BaseException as e:
    result['exc'] = repr(e)[:200]

